append:
/* The same tree finish in all active games, including free/editor/Endless.
   Paint only: existing padding, borders' widths, overflow and game coordinates
   stay unchanged. The root lives in the footer, outside clipped game surfaces. */
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > header{background:transparent;border-top-color:transparent}
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > header::after{content:"";position:absolute;inset:-88px 0 -9px;background:#fff;box-shadow:0 0 0 100vmax #fff;clip-path:inset(0 -100vmax);pointer-events:none;user-select:none;z-index:-1}
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) #main > .intro{position:relative;isolation:isolate;background:none;--hero-flare:max(14px,calc((100vw - 1280px)/2 + 4px))}
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) #main > .intro::before{content:"";position:absolute;inset:101px -24.5px 0;background:#fff;border:1px solid #b3c1a8;border-top:0;border-radius:0 0 12px 12px;pointer-events:none;user-select:none;z-index:-2}
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) #main > .intro::after{content:"";position:absolute;top:8px;left:calc(-24px - var(--hero-flare));width:calc(100% + 48px + 2 * var(--hero-flare));height:94px;background:url("platform-assets/soft-crown-left.svg") left/var(--hero-flare) 100% no-repeat,url("platform-assets/soft-crown-right.svg") right/var(--hero-flare) 100% no-repeat,linear-gradient(#fff,#fff) center/calc(100% - 2 * var(--hero-flare)) 100% no-repeat;pointer-events:none;user-select:none;z-index:-1}
#main > .lab:not([hidden]), #collection:not([hidden]) > .collection-lab{background:#fff;border-color:#b3c1a8;border-bottom-color:transparent;border-bottom-left-radius:0;border-bottom-right-radius:0}
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > footer{position:relative;isolation:isolate;z-index:1;background:transparent;border-top-color:transparent;border-bottom-color:transparent;box-shadow:none;--game-root-flare:max(38px,calc((100vw - 1280px)/2 + 28px))}
body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > footer::before{content:"";position:absolute;top:-2px;bottom:-113px;left:calc(40px - var(--game-root-flare) - .5px);width:calc(100% - 80px + 2 * var(--game-root-flare) + 1px);background:url("platform-assets/continuous-root-left.svg") left/var(--game-root-flare) 100% no-repeat,url("platform-assets/continuous-root-right.svg") right/var(--game-root-flare) 100% no-repeat,linear-gradient(#fff,#fff) center/calc(100% - 2 * var(--game-root-flare)) 100% no-repeat;filter:drop-shadow(0 2px 4px #34452a12);clip-path:inset(0 -12px -12px);pointer-events:none;user-select:none;z-index:-1}
@media(max-width:760px){
 body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > header::after{inset:-64px 0 -7px}
 body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) #main > .intro{--hero-flare:6px}
 body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) #main > .intro::before{inset:45px -8.5px 0;border-radius:0 0 9px 9px}
 body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) #main > .intro::after{top:6px;left:calc(-8px - var(--hero-flare));width:calc(100% + 16px + 2 * var(--hero-flare));height:40px}
 body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > footer{--game-root-flare:14px}
 body:has(.lab:not([hidden]), #collection:not([hidden]) > .collection-lab) > footer::before{left:calc(16px - var(--game-root-flare) - .5px);width:calc(100% - 32px + 2 * var(--game-root-flare) + 1px);bottom:-85px}
}
